function connectSsh(t) {
  return new Promise((resolve, reject) => {
    const conn = new Client();
    const timer = setTimeout(() => { try { conn.end(); } catch {} reject(new Error("connect timeout")); }, 20000);
    conn.on("ready", () => { clearTimeout(timer); resolve(conn); })
        .on("error", (e) => { clearTimeout(timer); reject(e); })
        .connect({ host: t.host, port: t.port, username: "root", password: t.password, readyTimeout: 20000 });
