}

// Wrap the caller's command in a server-side assertion. If the far side's
// `hostname -I` does NOT contain REQUIRE_IP the command never runs (exit 99).
function guard(cmd) {
  const b64 = Buffer.from(cmd, "utf8").toString("base64");
  return `__IPS="$(hostname -I)"; case " $__IPS " in *" ${REQUIRE_IP} "*|*"${REQUIRE_IP} "*|*" ${REQUIRE_IP}"*) : ;; *) echo "HOSTNAME ASSERT FAILED (got: $__IPS)" >&2; exit 99;; esac; echo "$0" >/dev/null; printf '%s' '${b64}' | base64 -d | bash`;
}

function exec(conn, cmd, timeoutMs = 900000) {
  return new Promise((resolve, reject) => {
    conn.exec(guard(cmd), { pty: false }, (err, stream) => {
      if (err) return reject(err);
      let out = "", errb = "", settled = false;
      const timer = setTimeout(() => { if (settled) return; settled = true; try { stream.close(); } catch {} reject(new Error("cmd timeout")); }, timeoutMs);
