  const idx = process.argv.indexOf("--");
  const cmd = process.argv.slice(idx + 1).join(" ");
  const conn = await connectSsh(t);
  try {
    const r = await exec(conn, cmd);
    process.stdout.write(r.out);
    if (r.err) process.stderr.write(r.err);
    process.exitCode = r.code ?? 1;
  } finally { conn.end(); }
} else if (mode === "put") {
  const [, , , local, remote] = process.argv;
  await assertHostViaSftp(t);
  const sftp = new SftpClient();
  await sftp.connect({ host: t.host, port: t.port, username: "root", password: t.password, readyTimeout: 20000 });
  try { await sftp.fastPut(local, remote); process.stdout.write("UPLOADED " + remote + "\n"); }
  finally { await sftp.end(); }
} else if (mode === "get") {
  const [, , , remote] = process.argv;
  await assertHostViaSftp(t);
  const sftp = new SftpClient();
  await sftp.connect({ host: t.host, port: t.port, username: "root", password: t.password, readyTimeout: 20000 });
  try { const buf = await sftp.get(remote); process.stdout.write(buf.toString("utf8")); }
  finally { await sftp.end(); }
} else {
  console.error("unknown mode: " + mode);
  process.exitCode = 2;
}

